       (.ext_reset_in(ext_reset_in),
        .lpf_int(lpf_int),
        .slowest_sync_clk(slowest_sync_clk));
  GND GND
       (.G(\<const0> ));
  design_1_cg_fpga_0_0_sequence_psr SEQ
       (.lpf_int(lpf_int),
        .pr_reg_0(SEQ_n_0),
        .slowest_sync_clk(slowest_sync_clk));
